static void
sz_boot_pind2sz_tab(const sc_data_t *sc_data) {
	int pind = 0;                            /* 输出索引，初值 0。有符号：用于循环边界判断 */
	for (unsigned i = 0; i < SC_NSIZES; i++) {  /* 扫全部 232 档，1:1 */
		const sc_t *sc = &sc_data->sc[i];          /* 第 i 档 sc指针，O(1) 索引 */
		if (sc->psz) {                              /* 过滤：只入表页整数倍档 (size % 4096 == 0) */
			sz_pind2sz_tab[pind] = (ZU(1) << sc->lg_base)
			    + (ZU(sc->ndelta) << sc->lg_delta); /* reg_size_compute 字节数 */
			pind++;                                 /* 仅当 psz=1 才推进输出索引 */
		}
		/* else: tiny/pseudo/小部分 small psz=0 跳过，pind 不动 */
	}
	/* 循环 2: 哨兵填充，从 pind=SC_NPSIZES 开始，多填 1 项 (SC_NPSIZES+1 表长) */
	for (int i = pind; i <= (int)SC_NPSIZES; i++) {
		sz_pind2sz_tab[pind] = sc_data->large_maxclass + PAGE; /* 哨兵 */
	}
}

